import typing
from datetime import date

from ledgerline import dates


def test_hints():
    assert typing.get_type_hints(dates.due_date) == {
        "issued": date, "terms_days": int, "return": date
    }
    assert typing.get_type_hints(dates.days_overdue) == {
        "due": date, "today": date, "return": int
    }
    assert typing.get_type_hints(dates.is_overdue) == {
        "due": date, "today": date, "return": bool
    }
